import { useEffect, useState, useCallback } from "react"
import earth from "../resources/images/earth.png"
import github from "../resources/images/github.png"
import { CellularAutomata1D } from "./cellular-automata/1d/cellularAutomata1D"
import { AutomataSelector } from "./cellular-automata/automata-selector"
import * as MIDI from "./performers/audio/MIDI"
import { getPremiumProgressions, getClassicalProgressions } from "./performers/audio/progressions-classical"
import { euclideanRhythm } from "./performers/audio/rhythms"
import CellularAutomataSketch from "./sketch/sketch"

export default function HumanMusic() {
   const [started, setStarted] = useState(false)
   const [loaded, setLoaded] = useState(false)
   const [automata, setAutomata] = useState<CellularAutomata1D | null>(null)
   const [showDebug, setShowDebug] = useState(false)

   useEffect(() => {
      if (!loaded) {
         MIDI.loadMidi(() => setLoaded(true))
      }
   }, [loaded])

   async function start() {
      await MIDI.resumeAudioContext()
      MIDI.start()
      setStarted(true)
      randomiseAutomata()
   }

   function randomiseAutomata() {
      const selector = new AutomataSelector()
      setAutomata(selector.randomSelection())
   }

   return (
      <div style={{ 
         textAlign: "center", 
         background: "#141414", 
         minHeight: "100vh",
         color: "white",
         fontFamily: "Arial, sans-serif"
      }}>
         
         {showDebug && (
            <div style={{
               position: "fixed",
               top: "10px",
               right: "10px",
               width: "200px",
               background: "rgba(0,0,0,0.95)",
               color: "#0f0",
               padding: "10px",
               borderRadius: "8px",
               fontFamily: "monospace",
               fontSize: "12px",
               zIndex: 1000,
               border: "1px solid #0f0"
            }}>
               <div style={{ display: "flex", justifyContent: "space-between" }}>
                  <strong>DEBUG</strong>
                  <button onClick={() => setShowDebug(false)} style={{ background: "#333", color: "#fff", border: "none", cursor: "pointer" }}>✕</button>
               </div>
               <p>Rule: {automata?.rule}</p>
               <button onClick={() => { console.log(getPremiumProgressions()[0]); randomiseAutomata(); }} style={{ background: "#222", color: "#0f0", border: "1px solid #0f0", padding: "4px 8px", margin: "2px", cursor: "pointer", fontSize: "11px" }}>🎵 Premium</button>
               <button onClick={() => { console.log(getClassicalProgressions()[0]); randomiseAutomata(); }} style={{ background: "#222", color: "#0f0", border: "1px solid #0f0", padding: "4px 8px", margin: "2px", cursor: "pointer", fontSize: "11px" }}>🎼 Classical</button>
               <br/>
               <button onClick={() => { console.log(euclideanRhythm(3,8,0)); randomiseAutomata(); }} style={{ background: "#222", color: "#0f0", border: "1px solid #0f0", padding: "4px 8px", margin: "2px", cursor: "pointer", fontSize: "11px" }}>🥁 3:8</button>
               <button onClick={() => { console.log(euclideanRhythm(5,8,0)); randomiseAutomata(); }} style={{ background: "#222", color: "#0f0", border: "1px solid #0f0", padding: "4px 8px", margin: "2px", cursor: "pointer", fontSize: "11px" }}>🥁 5:8</button>
            </div>
         )}

         <div style={{ padding: "20px" }}>
            <img src={earth} alt="Earth" style={{ width: "80px", cursor: "pointer" }} onClick={() => setShowDebug(true)} />
            <h1 style={{ color: "#b12525", margin: "10px 0" }}>Human Music</h1>
            <p style={{ margin: "5px 0" }}>by Earth Radio</p>
         </div>

         <div style={{ 
            width: "400px", 
            height: "400px", 
            margin: "20px auto",
            border: "2px solid white",
            background: "#090909"
         }}>
            {loaded && automata ? (
               <CellularAutomataSketch automata={automata} />
            ) : (
               <div style={{ paddingTop: "180px", color: "#666" }}>Loading...</div>
            )}
         </div>

         <div style={{ marginTop: "20px" }}>
            {started ? (
               <button 
                  onClick={randomiseAutomata}
                  style={{
                     padding: "10px 30px",
                     fontSize: "16px",
                     background: "#666",
                     color: "white",
                     border: "none",
                     cursor: "pointer"
                  }}
               >
                  Randomise
               </button>
            ) : (
               <button 
                  onClick={start}
                  disabled={!loaded}
                  style={{
                     padding: "10px 30px",
                     fontSize: "16px",
                     background: loaded ? "#666" : "#333",
                     color: "white",
                     border: "none",
                     cursor: loaded ? "pointer" : "not-allowed"
                  }}
               >
                  {loaded ? "Start" : "Loading..."}
               </button>
            )}
         </div>

         <div style={{ marginTop: "30px" }}>
            <a href="https://github.com/juankysoriano/human-music">
               <img src={github} alt="GitHub" style={{ width: "30px", filter: "invert(1)" }} />
            </a>
            <p style={{ fontSize: "14px", marginTop: "10px" }}>A mi padre ♥</p>
         </div>
      </div>
   )
}